+#define MAXLM 160
+#define WORDS 5 /* 2 LM <= 320 bits */
+_Static_assert(64 * WORDS >= 2 * MAXLM, "WORDS must hold 2 MAXLM bits");

 static int L, M, LM, W;

@@ -198,7 +199,10 @@
     L = atoi(argv[2]);
     M = atoi(argv[3]);
     LM = L * M;
